// FUNCTION ov95_021E623C: matching C (pt2)
#pragma force_active on
void ov95_021E623C(EggHatchCutscene *eggHatch) {
    PokemonSpriteTemplate monSpriteTemplate;
    SpriteAnimFrame animFrames[10];

    Pokemon *mon = eggHatch->app->args.mon;
    enum Species species = GetMonData(mon, MON_DATA_SPECIES_PT, ((void *)0));
    int yOffset = sub_0207083C(mon, 2);

    BOOL isEgg = 0;
    SetMonData(mon, MON_DATA_IS_EGG_PT, &isEgg);

    GetPokemonSpriteCharAndPlttNarcIds(&monSpriteTemplate, mon, 2);
    NARC_ReadPokepicAnimScript(eggHatch->graphics.monDataNarc, &animFrames[0], species, 1);

    eggHatch->monSprite = PokepicManager_CreatePokepic(eggHatch->graphics.monSpriteMan, &monSpriteTemplate, 256 / 2, (192 / 2) + yOffset, 0, 0, &animFrames[0], ((void *)0));
}
